using System;
using System.Collections.Generic;
using System.Linq;

public static class Rules
{
    // The caller decides what "change" means: double it, add tax, round it...
    public static List<int> Apply(List<int> values, Func<int, int> change)
    {
        var result = new List<int>();
        foreach (int v in values) result.Add(change(v));
        return result;
    }

    public static int CountWhere(List<int> values, Func<int, bool> test)
    {
        int n = 0;
        foreach (int v in values)
            if (test(v)) n++;
        return n;
    }

    // Returns a new function that remembers `factor`.
    public static Func<int, int> Multiplier(int factor) => x => x * factor;

    public static void Repeat(int times, Action<int> action)
    {
        for (int i = 1; i <= times; i++) action(i);
    }
}

