using System;
using System.Collections.Generic;
using System.Linq;

public class Health
{
    public int Max { get; }
    public int Current { get; private set; }

    public event Action<int> Changed;   // the new value
    public event Action Died;

    public Health(int max)
    {
        Max = max;
        Current = max;
    }

    public void Damage(int amount)
    {
        if (amount < 0) throw new ArgumentOutOfRangeException(nameof(amount));
        SetCurrent(Current - amount);
    }

    public void Heal(int amount)
    {
        if (amount < 0) throw new ArgumentOutOfRangeException(nameof(amount));
        SetCurrent(Current + amount);
    }

    // One place that changes Current, so the events can't be forgotten.
    private void SetCurrent(int value)
    {
        if (Current == 0) return;                 // dead stays dead
        int clamped = Math.Clamp(value, 0, Max);
        if (clamped == Current) return;           // nothing happened: stay quiet
        Current = clamped;
        Changed?.Invoke(Current);                 // ?. means: only if someone is listening
        if (Current == 0) Died?.Invoke();
    }
}

