using System;
using System.Collections.Generic;
using System.Linq;

public class WaveClearedEventArgs : EventArgs
{
    public int Wave { get; }
    public int Score { get; }

    public WaveClearedEventArgs(int wave, int score)
    {
        Wave = wave;
        Score = score;
    }
}

public class WaveManager
{
    public event EventHandler<WaveClearedEventArgs> WaveCleared;

    public int Wave { get; private set; }
    public int Remaining { get; private set; }
    public int TotalScore { get; private set; }

    private int waveScore;

    public void StartWave(int enemies)
    {
        if (enemies < 1) throw new ArgumentOutOfRangeException(nameof(enemies));
        if (Remaining > 0) throw new InvalidOperationException("Finish this wave first.");
        Wave++;
        Remaining = enemies;
        waveScore = 0;
    }

    public void EnemyKilled(int points)
    {
        if (Remaining == 0) throw new InvalidOperationException("No wave is running.");
        Remaining--;
        waveScore += points;
        TotalScore += points;
        if (Remaining == 0) OnWaveCleared(new WaveClearedEventArgs(Wave, waveScore));
    }

    // The usual .NET habit: one protected method that raises the event.
    protected virtual void OnWaveCleared(WaveClearedEventArgs e) => WaveCleared?.Invoke(this, e);
}
